interface Renderer {
  render(): string
}
class BaseRenderer implements Renderer {
  render() { return 'base' }
}
function addBorder(r: Renderer): Renderer {
  return { render: () => '<b>' + r.render() + '</b>' }
}
const r = addBorder(new BaseRenderer())
console.log(r.render())

interface Notifier { send(msg: string): void }
class EmailNotifier implements Notifier { send(msg: string) { console.log('email:' + msg) } }
function withEncryption(n: Notifier): Notifier { return { send: (m) => n.send('enc:' + m) } }
function withRetry(n: Notifier): Notifier { return { send: (m) => { try { n.send(m) } catch (e) { n.send(m) } } } }
const n = withRetry(withEncryption(new EmailNotifier()))
n.send('hello')

// Version A: monolithic feature flags
class FormatterA {
  constructor(private withBorder: boolean, private withUpper: boolean) {}
  render(s: string) {
    let out = s
    if (this.withUpper) out = out.toUpperCase()
    if (this.withBorder) out = '*' + out + '*'
    return out
  }
}

// Version B: small composable wrappers
interface Renderer { render(s: string): string }
class Base implements Renderer { render(s: string) { return s } }
class Upper implements Renderer { constructor(private r: Renderer) {} render(s: string) { return this.r.render(s).toUpperCase() } }
class Border implements Renderer { constructor(private r: Renderer) {} render(s: string) { return '*' + this.r.render(s) + '*' } }
const r = new Border(new Upper(new Base()))
console.log(r.render('hi'))
